  @override
  bool operator ==(Object other) =>
      other is StringField &&
      _equal(key, other.key) &&
      _equal(title, other.title) &&
      _equal(description, other.description) &&
      _equal(required, other.required) &&
      _equal(hidden, other.hidden) &&
      _equal(when, other.when) &&
      _equal(format, other.format) &&
      _equal(minLength, other.minLength) &&
      _equal(maxLength, other.maxLength) &&
      _equal(pattern, other.pattern) &&
      _equal(placeholder, other.placeholder) &&
      _equal(defaultValue, other.defaultValue) &&
      _equal(options, other.options) &&
      _equal(allowCustom, other.allowCustom);

  @override
  int get hashCode => Object.hashAll([
    _hash(key),
    _hash(title),
    _hash(description),
    _hash(required),
    _hash(hidden),
    _hash(when),
    _hash(format),
    _hash(minLength),
    _hash(maxLength),
    _hash(pattern),
    _hash(placeholder),
    _hash(defaultValue),
    _hash(options),
    _hash(allowCustom),
  ]);

  @override
  String toString() =>
      'StringField(key: $key, title: $title, description: $description, required: $required, hidden: $hidden, when: $when, format: $format, minLength: $minLength, maxLength: $maxLength, pattern: $pattern, placeholder: $placeholder, defaultValue: $defaultValue, options: $options, allowCustom: $allowCustom)';
}

enum StringFormat {
  email('email'),
  uri('uri'),
  date('date'),
  dateTime('date-time');

  const StringFormat(this.wire);

  factory StringFormat.fromJson(String json) => values.firstWhere(
    (value) => value.wire == json,
    orElse: () => throw FormatException('Unknown StringFormat: $json'),
  );

  final String wire;

  String toJson() => wire;
}

final class TextValue implements FormScalar, FormValue {
  const TextValue({required this.value});

  factory TextValue.fromJson(Map<String, Object?> json) {
    _expectShape(
      json,
      'TextValue',
      const <String>{'kind', 'value'},
      const <String, String>{'kind': 'text'},
    );
    return TextValue(value: _as<String>(json['value'], 'TextValue.value'));
  }

  final String value;

  @override
  Map<String, Object?> toJson() => {'kind': 'text', 'value': value};

  @override
  bool operator ==(Object other) =>
      other is TextValue && _equal(value, other.value);

  @override
  int get hashCode => Object.hashAll([_hash(value)]);

  @override
  String toString() => 'TextValue(value: $value)';
}
